-- GENERATED by `wfj generate` from data/gossip/gossip-7a.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["7a0fe69851efc9a3"] = { "Il mio padrone, Plugger Spazzring, è un buon capo. E fa un sacco di soldi. Ha le tasche che scoppiano!", "." },
  ["7a10659cedb097a8"] = { "Un potere incredibile si trova negli spiriti, o \"muisek\", delle creature contro cui combattiamo.\n\nGuarda dentro di te; impara a sfruttare il potere del tuo spirito, e diventerai più potente di quanto tu abbia mai immaginato.", "." },
  ["7a106de544fe7784"] = { "Durante la Guerra degli Antichi, il semidio Agamaggan si fece avanti per combattere la Legione Infuocata. Il colossale cinghiale fu sconfitto e, col tempo, nei luoghi dove era caduto il suo sangue spuntarono enormi rovi pieni di spine. I verrospini arrivarono a occupare queste regioni e a considerarle sacre. Il cuore di queste immense colonie di rovi è Lamaspina. Le ⟦Razorfen Kraul=Gallerie di Lamaspina⟧ sono state conquistate dalla megera Charlga Razorflank, che secondo alcuni tratta con agenti del Flagello per qualche scopo insidioso.", "." },
  ["7a13a2ffdedfbdb0"] = { "Se ho lettere indirizzate a {name}? Ma no! Direi che è ora che tu muoia!", "." },
  ["7a14559e71c7a69d"] = { "Il tuo cammino è saldo, {name}, perché la risolutezza di Washte Pawne è con te.", "." },
  ["7a16171941e67ed2"] = { "%s annuisce.", "." },
  ["7a175bac9e28b4ec"] = { "Ecco! Lavoro finito.", "." },
  ["7a1d1aa7abe8469b"] = { "Phalanx, credo che tu debba dare una lezione a questa persona.", "." },
  ["7a1eb3196ca6cac4"] = { "L'Occhio Onniveggente deve essere recuperato!", "." },
  ["7a2d46d19688ece8"] = { "D'accordo, andiamo.", "." },
  ["7a34245fca7943d5"] = { "Udite, udite! Mi fermerò a vendere la mia merce qui a ⟦Lakeshire=Borgolago⟧ solo per poco tempo. Venite subito al municipio!", "." },
  ["7a349eea8d790bb1"] = { "Hai quasi raggiunto l'apice del tuo addestramento. Per arrivare al massimo nell'arte dell'incantamento, ti resta un'ultima maestra da cercare. Si chiama Annora, e puoi trovarla a Uldaman.", "." },
  ["7a374449c1f3aa4a"] = { "Nagmara! È rimasto del montone?", "." },
  ["7a4a0f2e93147745"] = { "{name}! Come te la passi, <ragazzo/ragazza>? Fammi vedere cos'hai imparato dall'ultima volta che ti ho visto, così vediamo se c'è qualcosa di nuovo che posso insegnarti.", "." },
  ["7a4ba35becc5d59e"] = { "Mi spiace, <ragazzo/ragazza>, non sei ancora all'altezza di imparare da me. Va' da mio figlio Groum: un nuovo apprendista gli farebbe proprio piacere.", "." },
  ["7a4dae2795ccdd3e"] = { "L'ultima volta che ho saputo, l'anziano Stonespire era a ⟦Everlook=Lungavista⟧, a ⟦Winterspring=Fontefredda⟧.", "." },
  ["7a4ecbd2af1fce63"] = { "%s perde il collegamento!", "." },
  ["7a4f264e86866aea"] = { "%s toglie i semi dal ⟦Glowing Fruit=Frutto Brillante⟧...", "." },
  ["7a500cc0eb86fd4e"] = { "Dopo la caduta di Karazhan, il Kirin Tor inviò un gruppo di maghi a perquisire la torre e a sequestrare tutti gli oggetti importanti... a scopo di «ricerca». Fu allora che il leggendario bastone venne scoperto e riportato a Dalaran.", "." },
  ["7a54da5c95ec413e"] = { "Vendo i migliori abiti di stoffa e di cuoio da questa parte della valle!", "." },
  ["7a5aa35a51f944cb"] = { "Assaggia la magia dei ⟦Frostmane=Mantogelido⟧.", "." },
  ["7a5af2c27f7d2477"] = { "E adesso come faccio a cacciare quei maledetti aggeggi meccanici dai miei campi?", "." },
  ["7a5c191368a125e9"] = { "Hai fatto un buon lavoro, <viaggiatore/viaggiatrice>. È un orgoglio per me chiamarti <mio/mia> <allievo/allieva>!", "." },
  ["7a5cf2d8cfb206c1"] = { "%s implora il perdono di Impsy.", "." },
  ["7a5f524f60799d14"] = { "Uccidere te e i tuoi compari, {class}, mi divertirà. Farò in fretta.", "." },
  ["7a5ff82a4224bf3d"] = { "Aiutaci, <straniero/straniera>. <La reliquia si sbriciola in polvere. Una visione di otto nani ⟦Dark Iron=Ferroscuro⟧ che compiono una specie di rituale ti riempie la mente.>", "." },
  ["7a69b66703cbadce"] = { "Ora ho ciò che serve. Proseguiamo.", "." },
  ["7a8121584a7b06be"] = { "Onorato", "." },
  ["7a89529cbaac9dab"] = { "Raaaaaaaaaaaaaaaaaaaaaaaaaaaaaar!!! Io schiaccia {race}!", "." },
  ["7a8d4423cc028ec9"] = { "Sei <sicuro/sicura> di non voler fare il fabbro? Beh, se il tuo cuore ha scelto la conciatura, faresti meglio a parlare con Fimble Finespindle, nella sua bottega sul lato nord-ovest della ⟦Great Forge=Grande Forgia⟧.", "." },
  ["7a8db5d2fb872df9"] = { "Anathera... Non sopporto di affrontare il resto dell'eternità senza di te al mio fianco... Se mi verrai portata via, che questo sia il giorno in cui anch'io tornerò alla terra...", "." },
  ["7a910fe754a9d207"] = { "<Copio il modello nel mio diario.>.", "." },
  ["7a938cb21bfa3b58"] = { "Tu fa cappellino perfetto, {race}!", "." },
  ["7a965f5177807890"] = { "Dov'è la casa d'aste? Ma è proprio accanto ai cancelli di ⟦Ironforge=Forgiardente⟧, appena entri nella nostra bella città. La troverai proprio di fronte a The Vault.", "." },
  ["7a9c2ceb942e85d6"] = { "Il mio papà pesca più pesci del tuo papà!", "." },
  ["7aaa68757b99f666"] = { "Strano.", "." },
  ["7aadb15d825337d9"] = { "Ehi, che ti serve?", "." },
  ["7ab302d1872d155b"] = { "Le cose che ho fatto... cose così orribili...\n\n<Tarsis inizia a singhiozzare.>", "." },
  ["7abe00c543d45c00"] = { "Tutto il cibo e il materiale bellico che abbiamo raccolto è in viaggio verso ⟦Silithus=Silitus⟧. Dovrebbe arrivare in meno di un giorno. Qualcuno mi ha detto che, una volta radunato tutto vicino alla ⟦Cenarion Hold=Fortezza Cenariana⟧, qualcuno dovrà andare a suonare il gong all'Altare dello Scarabeo per aprire i cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧ e dare inizio alla guerra.", "." },
  ["7ac8e09c494cd076"] = { "Se intendi rubarmi tempo, faresti meglio a dimostrare che ne vale la pena. Dopotutto, qualcosa da questo accordo dovrò pur ricavarlo.", "." },
  ["7acb3cf1f156fe01"] = { "E dopo cosa le è successo?", "." },
  ["7ad3c2725b5c1eb5"] = { "Bah! Così non c'è gusto!", "." },
  ["7ade74b3ac479ce7"] = { "È stato un semplice errore. Ho sbagliato strada, te lo giuro!", "." },
  ["7ade992bc4d9be50"] = { "Credo di aver sentito parlare di questa magia.", "." },
  ["7ae461ae87913cc2"] = { "Mi spiace, ma non posso lasciarti montare i miei grifoni. Se ti serve un passaggio, parla con Gringer.", "." },
  ["7aed3943bdfa8679"] = { "%s fugge dopo aver visto cadere Kel'Thuzad!", "." },
  ["7af1c107dbefcb7c"] = { "Ho proprio il posto giusto per questo corno!", "." },
  ["7af1c575e233d0bd"] = { "Non mi piacciono queste città umane di pietra e acciaio. Preferirei le foreste di ⟦Ashenvale=Valtetra⟧, sulle tracce di grandi bestie. Ma il mio caro fratello, Kaerbrus, pensava che sarebbe stato utile addestrare gli umani nelle nostre arti. Perciò, anche se gli rendo onore e offro i miei servigi, non per questo deve piacermi.", "." },
  ["7af2d72741e14986"] = { "Non ci siamo appena liberati dalla Legione Infuocata, e tu vieni qui a trafficare di nuovo con i demoni? Cerca il Darkfire Enclave nella caverna sotterranea chiamata Cleft of Shadow. Troverai un tunnel che ci scende da The Drag.", "." },
  ["7afad67c47a985c2"] = { "Credi di avere ciò che serve per distruggere la ⟦The League of Arathor=Lega di Arathor⟧, {class}? Lo spero. Che cosa vuoi, o sei qui solo per farmi perdere tempo?", "." },
  ["7afaf794adbe73be"] = { "Forse un po' più di grasso farà al caso.", "." },
})
